<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/audit.php';require_once __DIR__.'/../includes/physician-withdrawals.php';
define('HQ_BASE_URL','..');requireRole(['Admin']);$user=currentUser();$pdo=getDbConnection();$errors=[];$flash=(string)($_SESSION['withdrawal_review_success']??'');unset($_SESSION['withdrawal_review_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){http_response_code(405);header('Allow: GET');exit('Demo withdrawals are now physician-controlled. Admin access is read-only.');}
$status=in_array($_GET['status']??'All',['All','Pending','PaidSimulated','Rejected'],true)?($_GET['status']??'All'):'All';$rows=[];
if($pdo){try{$sql='SELECT w.*,u.FirstName,u.LastName,owner.FirstName AS OwnerFirstName,owner.LastName AS OwnerLastName FROM PhysicianWithdrawals w JOIN Users u ON u.UserID=w.PhysicianID LEFT JOIN Users owner ON owner.UserID=w.FinancialOwnerUserID';$params=[];if($status!=='All'){$sql.=' WHERE w.Status=?';$params[]=$status;}$stmt=$pdo->prepare($sql.' ORDER BY w.WithdrawalID DESC LIMIT 100');$stmt->execute($params);$rows=$stmt->fetchAll();}catch(PDOException $e){error_log('Withdrawal review list failed: '.$e->getMessage());$errors[]='Withdrawal requests are temporarily unavailable.';}}
$isWithdrawalPage=true;$pageTitle='Physician withdrawals - HealthQueue';require __DIR__.'/../includes/header.php';
?>
<main class="admin-shell pw-page"><div class="container pw-container"><p class="pw-breadcrumb">Administration <span>/</span> Physician withdrawals</p><header class="pw-heading pw-heading-row"><div><h1>Physician withdrawals</h1><p>Monitor physician-controlled demo withdrawals. No Admin approval is required.</p></div><a class="btn btn-outline" href="revenue.php">Back to revenue</a></header>
