<div class="pw-demo">DEMO MODE &mdash; No real money transferred.</div>
<section class="pw-panel"><form class="pw-filter" method="get"><label>Status<select name="status"><?php foreach(['All'=>'All requests','Pending'=>'Pending','PaidSimulated'=>'Paid - Simulated','Rejected'=>'Rejected'] as $key=>$label): ?><option value="<?= $key ?>" <?= $key===$status?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button class="btn btn-outline">Apply filter</button></form>
<div class="pw-table-wrap"><table class="pw-table"><thead><tr><th>Reference</th><th>Physician</th><th>Requested</th><th>Amount</th><th>Destination</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($rows as $row): ?><tr><td><?= htmlspecialchars($row['Reference']) ?></td><td>Dr. <?= htmlspecialchars($row['FirstName'].' '.$row['LastName']) ?></td><td><?= htmlspecialchars(date('j M Y',strtotime($row['CreatedAt']))) ?></td><td>PHP <?= number_format((float)$row['Amount'],2) ?></td><td><?= htmlspecialchars(withdrawalMasked($row)) ?></td><td><span class="pw-status pw-status-<?= htmlspecialchars($row['Status']) ?>"><?= withdrawalStatus($row['Status']) ?></span></td><td><button class="btn btn-outline btn-sm" type="button" data-pw-open="review<?= (int)$row['WithdrawalID'] ?>">View details</button></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="7" class="pw-empty">No withdrawal requests match this filter.</td></tr><?php endif; ?></tbody></table></div></section></div></main>
<?php foreach($rows as $row): ?><dialog class="pw-dialog" id="review<?= (int)$row['WithdrawalID'] ?>" aria-labelledby="reviewTitle<?= (int)$row['WithdrawalID'] ?>"><button type="button" class="pw-close" data-pw-close aria-label="Close request">&times;</button><h2 id="reviewTitle<?= (int)$row['WithdrawalID'] ?>">Withdrawal details</h2><dl class="pw-details">
<?php foreach(['Reference'=>$row['Reference'],'Requested by'=>'Dr. '.$row['FirstName'].' '.$row['LastName'],'Main account'=>'Dr. '.($row['OwnerFirstName']??$row['FirstName']).' '.($row['OwnerLastName']??$row['LastName']),'Amount'=>'PHP '.number_format((float)$row['Amount'],2),'Method'=>$row['PayoutMethod'],'Account holder'=>$row['AccountName'],'Destination'=>$row['BankName']?:$row['PayoutMethod'],'Account number'=>$row['AccountNumber'],'Status'=>withdrawalStatus($row['Status']),'Requested'=>$row['CreatedAt'],'Reviewed'=>$row['ReviewedAt']?:'Not yet reviewed'] as $label=>$value): ?><div><dt><?= $label ?></dt><dd><?= htmlspecialchars($value) ?></dd></div><?php endforeach; ?></dl>
<p class="pw-dialog-note">Monitoring only. No bank or e-wallet transfer occurs. Earlier pending reservations can be confirmed by their main physician.</p></dialog><?php endforeach; ?>
